<?php require_once __DIR__ . '/includes/init.php'; redirect_if_logged_in(); $errors=[]; $next=safe_redirect_target($_GET['next']??'account.php'); if ($_SERVER['REQUEST_METHOD']==='POST') { require_csrf(); $identity=strtolower(trim((string)($_POST['identity']??''))); $password=(string)($_POST['password']??''); $user=$identity?db_one("SELECT * FROM users WHERE (LOWER(email)=? OR LOWER(username)=?) AND is_active=1 AND (status IS NULL OR status='active') LIMIT 1",[$identity,$identity]):null; if (!$user || !password_verify($password,(string)$user['password_hash'])) $errors[]='Email/username or password is incorrect.'; else { login_user($user,!empty($_POST['remember'])); $_SESSION['user_role']=(string)($user['role']??'customer'); if (in_array($_SESSION['user_role'],['staff','admin','super_admin'],true) && $next==='account.php') $next='admin/index.php'; redirect($next); } } $pageTitle='Log in'; require __DIR__.'/includes/header.php'; ?><main class="container auth-page"><div class="auth-card"><p class="eyebrow">Welcome back</p><h1>Log in to BFM</h1><?php foreach($errors as $error): ?><div class="alert alert-error"><?=e($error)?></div><?php endforeach; ?><form method="post" class="form-stack"><?=csrf_field()?><label>Email or username<input name="identity" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><label class="check"><input type="checkbox" name="remember"> Remember me</label><button class="btn btn-primary btn-block">Log in</button></form><p class="auth-link">New here? <a href="<?=e(url('register.php'))?>">Create an account</a></p></div></main><?php require __DIR__.'/includes/footer.php'; ?>
